	io_m_axis_task_bits,
	io_readTasksCount_ready,
	io_readTasksCount_valid,
	io_readTasksCount_bits,
	io_fpgaId
);
	input clock;
	input reset;
	output wire io_connNetwork_ctrl_stealReq_valid;
	input io_connNetwork_ctrl_stealReq_ready;
	output wire io_connNetwork_data_availableTask_ready;
	input io_connNetwork_data_availableTask_valid;
	input [511:0] io_connNetwork_data_availableTask_bits;
	input io_m_axis_task_ready;
	output wire io_m_axis_task_valid;
	output wire [511:0] io_m_axis_task_bits;
	output wire io_readTasksCount_ready;
	input io_readTasksCount_valid;
	input [31:0] io_readTasksCount_bits;
	input [63:0] io_fpgaId;
	reg startTokenReceived;
	reg [31:0] readTasksCountReg;
	reg [31:0] allowCount;
	wire io_connNetwork_ctrl_stealReq_valid_0 = (startTokenReceived & (allowCount < readTasksCountReg)) & io_m_axis_task_ready;
	reg [31:0] tasksRead;
	wire _GEN = startTokenReceived & (tasksRead < allowCount);
	wire io_connNetwork_data_availableTask_ready_0 = _GEN & io_m_axis_task_ready;
	reg [31:0] readTaskCounter;
	reg [31:0] cyclesCounter;
	wire _GEN_0 = cyclesCounter == 32'h000186a0;
	always @(posedge clock)
		if ((1 & _GEN_0) & ~reset) begin
			$fwrite(32'h80000002, "_______\n");
			$fwrite(32'h80000002, "FPGA ID: %d, Number of tasks read from the local network: %d\n", io_fpgaId, readTaskCounter);
			$fwrite(32'h80000002, "_______\n");
		end
	always @(posedge clock)
		if (reset) begin
			startTokenReceived <= 1'h0;
			readTasksCountReg <= 32'h00000000;
			allowCount <= 32'h00000000;
			tasksRead <= 32'h00000000;
			readTaskCounter <= 32'h00000000;
			cyclesCounter <= 32'h00000000;
		end
		else begin : sv2v_autoblock_1
			reg _GEN_1;
			reg _GEN_2;
			reg _GEN_3;
			_GEN_3 = startTokenReceived & (tasksRead == readTasksCountReg);
			_GEN_1 = ~startTokenReceived & io_readTasksCount_valid;
			_GEN_2 = io_connNetwork_data_availableTask_ready_0 & io_connNetwork_data_availableTask_valid;
			startTokenReceived <= ~_GEN_3 & (_GEN_1 | startTokenReceived);
			if (_GEN_3) begin
				readTasksCountReg <= 32'h00000000;
				allowCount <= 32'h00000000;
				tasksRead <= 32'h00000000;
			end
			else begin
				if (_GEN_1)
					readTasksCountReg <= io_readTasksCount_bits;
				if (io_connNetwork_ctrl_stealReq_valid_0 & io_connNetwork_ctrl_stealReq_ready)
					allowCount <= allowCount + 32'h00000001;
				if (_GEN & _GEN_2)
					tasksRead <= tasksRead + 32'h00000001;
			end
			if (_GEN_2)
				readTaskCounter <= readTaskCounter + 32'h00000001;
			if (_GEN_0)
				cyclesCounter <= 32'h00000000;
			else
				cyclesCounter <= cyclesCounter + 32'h00000001;
		end
	assign io_connNetwork_ctrl_stealReq_valid = io_connNetwork_ctrl_stealReq_valid_0;
	assign io_connNetwork_data_availableTask_ready = io_connNetwork_data_availableTask_ready_0;
	assign io_m_axis_task_valid = _GEN & io_connNetwork_data_availableTask_valid;
	assign io_m_axis_task_bits = (_GEN ? io_connNetwork_data_availableTask_bits : 512'h0);
	assign io_readTasksCount_ready = ~startTokenReceived;
endmodule
