	wire _chooser_rrChoice_T_4 = (chooser_lastChoice == 2'h0) & io_sources_1_valid;
	wire [1:0] chooser_rrChoice = (&chooser_lastChoice ? 2'h0 : (_chooser_rrChoice_T_4 ? 2'h1 : 2'h2));
	wire [1:0] chooser_priorityChoice = (io_sources_0_valid ? 2'h0 : (io_sources_1_valid ? 2'h1 : 2'h2));
	wire [3:0] _GEN = {io_sources_0_valid, io_sources_2_valid, io_sources_1_valid, io_sources_0_valid};
	wire [1:0] choice = (_GEN[chooser_rrChoice] ? chooser_rrChoice : chooser_priorityChoice);
	wire [4095:0] _GEN_0 = {io_sources_0_bits_data, io_sources_2_bits_data, io_sources_1_bits_data, io_sources_0_bits_data};
	wire [511:0] _GEN_1 = {io_sources_0_bits_strobe, io_sources_2_bits_strobe, 128'hffffffffffffffffffffffffffffffff, io_sources_0_bits_strobe};
	wire [511:0] _GEN_2 = {io_sources_0_bits_keep, io_sources_2_bits_keep, 128'hffffffffffffffffffffffffffffffff, io_sources_0_bits_keep};
	wire [3:0] _GEN_3 = {io_sources_0_bits_last, io_sources_2_bits_last, 1'h1, io_sources_0_bits_last};
	wire [15:0] _GEN_4 = {io_sources_0_bits_dest, io_sources_2_bits_dest, io_sources_1_bits_dest, io_sources_0_bits_dest};
