					chooser_lastChoice <= 2'h0;
				else if (_chooser_rrChoice_T_4)
					chooser_lastChoice <= 2'h1;
				else
					chooser_lastChoice <= 2'h2;
			end
			else
				chooser_lastChoice <= chooser_priorityChoice;
		end
