	input W0_addr;
	input W0_en;
	input W0_clk;
	input [511:0] W0_data;
	reg [511:0] Memory [0:1];
	always @(posedge W0_clk)
		if (W0_en & 1'h1)
			Memory[W0_addr] <= W0_data;
	assign R0_data = (R0_en ? Memory[R0_addr] : 512');
endmodule
module Queue2_UInt512 (
	clock,
	reset,
	io_enq_ready,
	io_enq_valid,
	io_enq_bits,
